{
  onAdd: function(map, gl) {
    this.map = map;
    this.gl = gl;

    // Vertex shader - applies height-based color gradient
    const vertexSource = `
      uniform mat4 u_matrix;
      attribute vec2 a_pos;
      attribute float a_height;
      varying float v_height;

      void main() {
        v_height = a_height;
        vec4 pos = vec4(a_pos, a_height, 1.0);
        gl_Position = u_matrix * pos;
      }
    `;

    // Fragment shader - interpolates color based on height
    const fragmentSource = `
      precision mediump float;
      uniform vec3 u_baseColor;
      uniform vec3 u_topColor;
      uniform float u_heightScale;
      varying float v_height;

      void main() {
        float t = clamp(v_height * u_heightScale, 0.0, 1.0);
        vec3 color = mix(u_baseColor, u_topColor, t);
        gl_FragColor = vec4(color, 0.8);
      }
    `;

    // Create shader program
    const vertexShader = gl.createShader(gl.VERTEX_SHADER);
    gl.shaderSource(vertexShader, vertexSource);
    gl.compileShader(vertexShader);

    const fragmentShader = gl.createShader(gl.FRAGMENT_SHADER);
    gl.shaderSource(fragmentShader, fragmentSource);
    gl.compileShader(fragmentShader);

    this.program = gl.createProgram();
    gl.attachShader(this.program, vertexShader);
    gl.attachShader(this.program, fragmentShader);
    gl.linkProgram(this.program);

    // Store attribute and uniform locations
    this.aPos = gl.getAttribLocation(this.program, 'a_pos');
    this.aHeight = gl.getAttribLocation(this.program, 'a_height');
    this.uMatrix = gl.getUniformLocation(this.program, 'u_matrix');
    this.uBaseColor = gl.getUniformLocation(this.program, 'u_baseColor');
    this.uTopColor = gl.getUniformLocation(this.program, 'u_topColor');
    this.uHeightScale = gl.getUniformLocation(this.program, 'u_heightScale');

    console.log('3D building gradient layer initialized');
  },

  render: function(gl, matrix) {
    if (!this.program) return;

    gl.useProgram(this.program);
    gl.uniformMatrix4fv(this.uMatrix, false, matrix);

    // Apply gradient colors from params
    const baseColor = params.baseColor || [0.2, 0.3, 0.5];
    const topColor = params.topColor || [0.8, 0.9, 1.0];
    const heightScale = params.heightScale || 0.01;

    gl.uniform3fv(this.uBaseColor, baseColor);
    gl.uniform3fv(this.uTopColor, topColor);
    gl.uniform1f(this.uHeightScale, heightScale);

    // Enable blending for transparency
    gl.enable(gl.BLEND);
    gl.blendFunc(gl.SRC_ALPHA, gl.ONE_MINUS_SRC_ALPHA);

